// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address owner = address(this);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent, "initial send failed");
        bytes memory empty;
        bool ok;
        try c.Command(owner, empty) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
